}

export function ConfigSectionLayout(props: ConfigSectionLayoutProps) {
    const { disabled = false, draft, entries, id, label, onChange, onValidityChange } = props
    const headingId = `${id}-config-heading`

    return (
        <Box
            aria-labelledby={headingId}
            component="section"
            id={id}
            sx={{ scrollMarginTop: CONFIG_SECTION_SCROLL_MARGIN_TOP }}
        >
            <Stack spacing={3}>
                <Typography component="h3" id={headingId} variant="h6">
                    {label}
                </Typography>
                {entries.map((entry) => (
                    <ConfigValueEditor
                        disabled={disabled}
                        entry={entry}
                        key={entry.key}
                        onChange={onChange}
                        onValidityChange={onValidityChange}
                        value={draft[entry.key]}
                        values={draft}
                    />
                ))}
            </Stack>
        </Box>
    )
}
